"""CRUD endpoints for organizers."""

from typing import Annotated

from fastapi import APIRouter, Depends, HTTPException, Query, Response, status
from sqlalchemy import select
from sqlalchemy.orm import Session

from app.db import get_session
from app.models import Organizer
from app.schemas import OrganizerCreate, OrganizerRead, OrganizerUpdate

router = APIRouter(prefix="/organizers", tags=["organizers"])
SessionDep = Annotated[Session, Depends(get_session)]


def _get_or_404(session: Session, organizer_id: int) -> Organizer:
    organizer = session.get(Organizer, organizer_id)
    if organizer is None:
        raise HTTPException(status.HTTP_404_NOT_FOUND, detail="Organizer not found")
    return organizer


@router.get("", response_model=list[OrganizerRead])
def list_organizers(
    session: SessionDep,
    limit: Annotated[int, Query(ge=1, le=200)] = 50,
    offset: Annotated[int, Query(ge=0)] = 0,
) -> list[Organizer]:
    query = select(Organizer).order_by(Organizer.id).offset(offset).limit(limit)
    return list(session.scalars(query))


@router.post("", response_model=OrganizerRead, status_code=status.HTTP_201_CREATED)
def create_organizer(payload: OrganizerCreate, session: SessionDep) -> Organizer:
    organizer = Organizer(**payload.model_dump())
    session.add(organizer)
    session.commit()
    session.refresh(organizer)
    return organizer


@router.get("/{organizer_id}", response_model=OrganizerRead)
def get_organizer(organizer_id: int, session: SessionDep) -> Organizer:
    return _get_or_404(session, organizer_id)


@router.patch("/{organizer_id}", response_model=OrganizerRead)
def update_organizer(
    organizer_id: int,
    payload: OrganizerUpdate,
    session: SessionDep,
) -> Organizer:
    organizer = _get_or_404(session, organizer_id)
    for key, value in payload.model_dump(exclude_unset=True).items():
        setattr(organizer, key, value)
    session.commit()
    session.refresh(organizer)
    return organizer


@router.delete("/{organizer_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_organizer(organizer_id: int, session: SessionDep) -> Response:
    session.delete(_get_or_404(session, organizer_id))
    session.commit()
    return Response(status_code=status.HTTP_204_NO_CONTENT)

from fastapi.testclient import TestClient

PAYLOAD = {
    "name": "example name",
    "description": "Some longer description text.",
}


def test_create_and_get_organizer(client: TestClient) -> None:
    response = client.post("/organizers", json=PAYLOAD)
    assert response.status_code == 201, response.text
    created = response.json()
    assert created["name"] == "example name"
    assert created["description"] == "Some longer description text."
    fetched = client.get(f"/organizers/{created['id']}")
    assert fetched.status_code == 200
    assert fetched.json()["id"] == created["id"]


def test_list_organizer_supports_pagination(client: TestClient) -> None:
    for _ in range(3):
        assert client.post("/organizers", json=PAYLOAD).status_code == 201
    page = client.get("/organizers", params={"limit": 2, "offset": 1})
    assert page.status_code == 200
    assert len(page.json()) == 2


def test_update_organizer(client: TestClient) -> None:
    created = client.post("/organizers", json=PAYLOAD).json()
    response = client.patch(
        f"/organizers/{created['id']}", json={"name": "updated name"}
    )
    assert response.status_code == 200
    assert response.json()["name"] == "updated name"


def test_delete_organizer(client: TestClient) -> None:
    created = client.post("/organizers", json=PAYLOAD).json()
    assert client.delete(f"/organizers/{created['id']}").status_code == 204
    assert client.get(f"/organizers/{created['id']}").status_code == 404


def test_unknown_organizer_returns_404(client: TestClient) -> None:
    assert client.get("/organizers/999999").status_code == 404


def test_create_organizer_rejects_missing_required_fields(client: TestClient) -> None:
    assert client.post("/organizers", json={}).status_code == 422

